WITH base AS (SELECT *, YEAR(reading_ts) AS reading_ts_year FROM device_readings WHERE reading_ts >= DATE '2025-09-01') SELECT id, temp_c, pressure, status_bits, CORR(pressure, humidity) OVER (PARTITION BY YEAR(reading_ts), device_code) AS corr_pressure_humidity, FIRST_VALUE(pressure) IGNORE NULLS OVER (PARTITION BY YEAR(reading_ts) ORDER BY pressure, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_pressure, MAX(pressure) OVER w_running AS pressure_max_2h FROM base WINDOW w_running AS (PARTITION BY device_code ORDER BY CAST(reading_ts AS BIGINT) RANGE BETWEEN 7200 PRECEDING AND CURRENT ROW);
